#include "history.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static const char *DDL =
    "CREATE TABLE IF NOT EXISTS history("
    "id INTEGER PRIMARY KEY AUTOINCREMENT,url TEXT NOT NULL,status TEXT NOT NULL,"
    "started_at TEXT NOT NULL,finished_at TEXT,document_title TEXT,saved_path TEXT,error_message TEXT);"
    "CREATE INDEX IF NOT EXISTS idx_history_started_id ON history(started_at DESC,id DESC);";

static void set_error(char *out,size_t cap,const char *s){if(out&&cap){snprintf(out,cap,"%s",s?s:"Unknown SQLite error");out[cap-1]='\0';}}
static char *copy_text(const char*s){if(!s)return NULL;size_t n=strlen(s);char*p=(char*)malloc(n+1);if(p)memcpy(p,s,n+1);return p;}
static void timestamp(char out[20]){SYSTEMTIME t;GetLocalTime(&t);snprintf(out,20,"%04u-%02u-%02uT%02u:%02u:%02u",t.wYear,t.wMonth,t.wDay,t.wHour,t.wMinute,t.wSecond);}
static int open_db(ZDSqliteApi*api,const char*path,sqlite3**db,char*error,size_t cap){*db=NULL;int rc=api->open_v2(path,db,ZD_SQLITE_OPEN_READWRITE|ZD_SQLITE_OPEN_CREATE|ZD_SQLITE_OPEN_FULLMUTEX,NULL);if(rc!=ZD_SQLITE_OK){set_error(error,cap,*db?api->errmsg(*db):"Cannot open SQLite database");if(*db){api->close(*db);*db=NULL;}return 0;}rc=api->busy_timeout(*db,5000);if(rc!=ZD_SQLITE_OK){set_error(error,cap,api->errmsg(*db));api->close(*db);*db=NULL;return 0;}char*msg=NULL;rc=api->exec(*db,DDL,NULL,NULL,&msg);if(rc!=ZD_SQLITE_OK){set_error(error,cap,msg?msg:api->errmsg(*db));if(msg)api->free_mem(msg);api->close(*db);*db=NULL;return 0;}return 1;}
static int bind_text(ZDSqliteApi*api,sqlite3_stmt*st,int i,const char*s){return api->bind_text(st,i,s?s:"",-1,ZD_SQLITE_TRANSIENT)==ZD_SQLITE_OK;}
static int bind_nullable(ZDSqliteApi*api,sqlite3_stmt*st,int i,const char*s){return s?bind_text(api,st,i,s):api->bind_text(st,i,NULL,0,NULL)==ZD_SQLITE_OK;}
int zd_history_start(ZDSqliteApi*api,const char*db_path,const char*url,int64_t*entry_id,char*error,size_t cap){if(error&&cap)error[0]=0;if(entry_id)*entry_id=0;if(!api||!db_path||!url){set_error(error,cap,"Invalid history arguments.");return 0;}sqlite3*db=NULL;if(!open_db(api,db_path,&db,error,cap))return 0;sqlite3_stmt*st=NULL;const char*sql="INSERT INTO history(url,status,started_at) VALUES(?,?,?)";int ok=api->prepare_v2(db,sql,-1,&st,NULL)==ZD_SQLITE_OK;char now[20];timestamp(now);if(ok)ok=bind_text(api,st,1,url)&&bind_text(api,st,2,"Розпочато")&&bind_text(api,st,3,now);if(ok)ok=api->step(st)==ZD_SQLITE_DONE;if(!ok)set_error(error,cap,api->errmsg(db));if(st)api->finalize(st);if(ok&&entry_id){sqlite3_stmt*q=NULL;if(api->prepare_v2(db,"SELECT last_insert_rowid()",-1,&q,NULL)==ZD_SQLITE_OK&&api->step(q)==ZD_SQLITE_ROW)*entry_id=api->column_int64(q,0);if(q)api->finalize(q);}api->close(db);return ok;}
int zd_history_finish(ZDSqliteApi*api,const char*db_path,int64_t id,const char*status,const char*title,const char*path,const char*message,char*error,size_t cap){if(error&&cap)error[0]=0;if(!api||!db_path||id<=0||!status){set_error(error,cap,"Invalid history update.");return 0;}sqlite3*db=NULL;if(!open_db(api,db_path,&db,error,cap))return 0;sqlite3_stmt*st=NULL;const char*sql="UPDATE history SET status=?,finished_at=?,document_title=?,saved_path=?,error_message=? WHERE id=?";int ok=api->prepare_v2(db,sql,-1,&st,NULL)==ZD_SQLITE_OK;char now[20];timestamp(now);if(ok)ok=bind_text(api,st,1,status)&&bind_text(api,st,2,now)&&bind_nullable(api,st,3,title)&&bind_nullable(api,st,4,path)&&bind_nullable(api,st,5,message)&&api->bind_int64(st,6,(long long)id)==ZD_SQLITE_OK;if(ok)ok=api->step(st)==ZD_SQLITE_DONE;if(!ok)set_error(error,cap,api->errmsg(db));if(st)api->finalize(st);api->close(db);return ok;}
static char *column_copy(ZDSqliteApi*api,sqlite3_stmt*st,int col){const unsigned char*p=api->column_text(st,col);return p?copy_text((const char*)p):NULL;}
void zd_history_free(ZDHistoryList*list){if(!list)return;for(size_t i=0;i<list->count;i++){ZDHistoryEntry*e=&list->items[i];free(e->url);free(e->status);free(e->started_at);free(e->finished_at);free(e->document_title);free(e->saved_path);free(e->error_message);}free(list->items);list->items=NULL;list->count=0;}
int zd_history_load(ZDSqliteApi*api,const char*db_path,ZDHistoryList*list,char*error,size_t cap){if(error&&cap)error[0]=0;if(!api||!db_path||!list){set_error(error,cap,"Invalid history query.");return 0;}list->items=NULL;list->count=0;sqlite3*db=NULL;if(!open_db(api,db_path,&db,error,cap))return 0;sqlite3_stmt*st=NULL;const char*sql="SELECT id,url,status,started_at,finished_at,document_title,saved_path,error_message FROM history ORDER BY started_at DESC,id DESC";int ok=api->prepare_v2(db,sql,-1,&st,NULL)==ZD_SQLITE_OK;if(!ok)set_error(error,cap,api->errmsg(db));size_t capacity=0;while(ok){int rc=api->step(st);if(rc==ZD_SQLITE_DONE)break;if(rc!=ZD_SQLITE_ROW){set_error(error,cap,api->errmsg(db));ok=0;break;}ZDHistoryEntry e={0};e.id=api->column_int64(st,0);e.url=column_copy(api,st,1);e.status=column_copy(api,st,2);e.started_at=column_copy(api,st,3);e.finished_at=column_copy(api,st,4);e.document_title=column_copy(api,st,5);e.saved_path=column_copy(api,st,6);e.error_message=column_copy(api,st,7);if(!e.url||!e.status||!e.started_at){free(e.url);free(e.status);free(e.started_at);free(e.finished_at);free(e.document_title);free(e.saved_path);free(e.error_message);set_error(error,cap,"Out of memory loading history.");ok=0;break;}if(list->count==capacity){size_t next=capacity?capacity*2:64;ZDHistoryEntry*p=(ZDHistoryEntry*)realloc(list->items,next*sizeof(*p));if(!p){free(e.url);free(e.status);free(e.started_at);free(e.finished_at);free(e.document_title);free(e.saved_path);free(e.error_message);set_error(error,cap,"Out of memory loading history.");ok=0;break;}list->items=p;capacity=next;}list->items[list->count++]=e;}if(st)api->finalize(st);api->close(db);if(!ok)zd_history_free(list);return ok;}
